-- V2__multiempresa.sql
-- Transforma o InfoFolga em multiempresa: cada colaborador e cada solicitação pertencem a uma empresa.
-- Os dados que já existem passam a ser da Infoway (empresa 1).
-- Rodar UMA vez, com a API parada, depois de um backup. Tudo dentro de uma transação: se algo falhar, nada muda.

BEGIN;

CREATE TABLE empresas (
    id BIGSERIAL PRIMARY KEY,
    nome VARCHAR(255) NOT NULL,
    logo TEXT,
    logo_relatorio TEXT
);

INSERT INTO empresas (id, nome, logo, logo_relatorio) VALUES (
    1,
    'Infoway Telecom',
    'data:image/png;base64,',
    'data:image/png;base64,'
);
SELECT setval('empresas_id_seq', (SELECT MAX(id) FROM empresas));

ALTER TABLE colaboradores ADD COLUMN empresa_id BIGINT;
UPDATE colaboradores SET empresa_id = 1;
ALTER TABLE colaboradores ALTER COLUMN empresa_id SET NOT NULL;
ALTER TABLE colaboradores ADD CONSTRAINT fk_colaboradores_empresa FOREIGN KEY (empresa_id) REFERENCES empresas(id);
CREATE INDEX idx_colaboradores_empresa_id ON colaboradores(empresa_id);

ALTER TABLE solicitacoes ADD COLUMN empresa_id BIGINT;
UPDATE solicitacoes SET empresa_id = 1;
ALTER TABLE solicitacoes ALTER COLUMN empresa_id SET NOT NULL;
ALTER TABLE solicitacoes ADD CONSTRAINT fk_solicitacoes_empresa FOREIGN KEY (empresa_id) REFERENCES empresas(id);
CREATE INDEX idx_solicitacoes_empresa_id ON solicitacoes(empresa_id);

COMMIT;
